class GymMemberLevel { protected String memberId; protected int monthlyFee; protected int sessionsAttended; public GymMemberLevel(String memberId, int monthlyFee) { if (memberId == null || memberId.trim().isEmpty() || memberId.length() < 4) throw new IllegalArgumentException("Invalid member ID"); this.memberId = memberId; this.monthlyFee = monthlyFee; this.sessionsAttended = 0; } public void attendSession() { sessionsAttended++; } public int getSessionsAttended() { return sessionsAttended; } public void displayInfo() { System.out.println("Standard Member | Sessions: " + sessionsAttended); } }
class PremiumGymLevel extends GymMemberLevel { protected String trainerName; public PremiumGymLevel(String memberId, int monthlyFee, String trainerName) { super(memberId, monthlyFee); this.trainerName = trainerName; } @Override public void displayInfo() { System.out.println("Premium Member | Trainer: " + trainerName + " | Sessions: " + sessionsAttended); } }
class EliteGymLevel extends PremiumGymLevel { private String lockerNumber; public EliteGymLevel(String memberId, int monthlyFee, String trainerName, String lockerNumber) { super(memberId, monthlyFee, trainerName); this.lockerNumber = lockerNumber; } @Override public void displayInfo() { System.out.println("Elite Member | Trainer: " + trainerName + " | Locker: " + lockerNumber + " | Sessions: " + sessionsAttended); } }
class GroupClassGymLevel extends GymMemberLevel { private String className; public GroupClassGymLevel(String memberId, int monthlyFee, String className) { super(memberId, monthlyFee); this.className = className; } @Override public void displayInfo() { System.out.println("Group Class Member | Class: " + className + " | Sessions: " + sessionsAttended); } }
public class GymMembershipHierarchy { static String classifyGeneration(GymMemberLevel member) { if (member instanceof EliteGymLevel) return "Multilevel descendant (3 generations deep)"; if (member instanceof GroupClassGymLevel) return "Hierarchical sibling (independent branch)"; if (member instanceof PremiumGymLevel) return "Premium Member"; return "Standard Member"; } static int getTotalSessionsAttended(GymMemberLevel[] members) { int total = 0; for (GymMemberLevel member : members) total += member.getSessionsAttended(); return total; } public static void main(String[] args) { GymMemberLevel standard = new GymMemberLevel("MEM1", 1000); PremiumGymLevel premium = new PremiumGymLevel("MEM2", 2000, "Coach Riya"); EliteGymLevel elite = new EliteGymLevel("MEM3", 3000, "Coach Arjun", "L12"); GroupClassGymLevel group = new GroupClassGymLevel("MEM4", 1500, "Zumba"); standard.displayInfo(); premium.displayInfo(); elite.displayInfo(); group.displayInfo(); System.out.println(classifyGeneration(elite)); System.out.println(classifyGeneration(group)); premium.attendSession(); premium.attendSession(); premium.attendSession(); elite.attendSession(); elite.attendSession(); group.attendSession(); group.attendSession(); group.attendSession(); group.attendSession(); GymMemberLevel[] members = {premium, elite, group}; System.out.println(getTotalSessionsAttended(members)); } }